local Levels=require 'audio.AudioLevels'
V.atFrame(2,function()
 local records={};local store={Read=function(_,key,valid)local value=records[key];return valid(value) and value or nil end,
  Write=function(_,key,value,valid)V.assert(valid(value),'audio persisted payload passes validator');records[key]=value;return true end}
 Levels.Init(store);V.assert(Levels.Get('sfx')==.65 and Levels.Get('music')==.75 and Levels.Get('voice')==.6,'frozen three default levels')
 local seen={};local off=Levels.On('voice',function(value)seen[#seen+1]=value end)
 Levels.Set('voice',.3);V.assert(#seen==2 and seen[1]==.6 and seen[2]==.3,'voice subscription immediately updates then receives changes')
 off();Levels.Set('voice',.2);V.assert(#seen==2,'unsubscribe removes retained callback')
 Levels.Init(store);V.assert(Levels.Get('voice')==.2,'persisted audio controls restore')
 local nan=string.unpack('<d',string.pack('<I8',0x7ff8000000000001))
 V.assert(not Levels.Set('sfx',nan) and not Levels.Set('unknown',.4),'reject invalid volume channel and decoded IEEE NaN')
 local posInf=string.unpack('<d',string.pack('<I8',0x7ff0000000000000));local negInf=string.unpack('<d',string.pack('<I8',0xfff0000000000000))
 V.assert(not Levels.Set('sfx',posInf) and not Levels.Set('voice',negInf),'reject both decoded IEEE infinite audio settings')
 V.assert(not Levels.Valid({sfx=.5,music=.5,voice=.5,musicEnabled='yes'}),'reject malformed persisted enabled flag')
 for _,value in ipairs({0,.1,.25,.5,.75,1}) do local want=value==0 and 0 or 10^(-36*(1-value)/20);V.assert(math.abs(Levels.MusicGain(value)-want)<1e-12,'source logarithmic music level '..value) end
 Levels.Init(nil)
 local Audio=require 'audio.IntroAudio';local intro=Audio.New({audio={},durations={}})
 local sound=cache:GetResource('Sound','Intro/Audio/sfx_blip.mp3');V.assert(sound and sound.length>0,'original intro waveform decodes')
 intro.sounds.sfx_blip=sound;intro.sounds.test=sound
 intro:Sfx('blip',{vol=.2});local slot=intro.sources[1];local base=.2*2*.9
 V.assert(math.abs(slot.source.gain-base*.65)<1e-6,'source opening SFX uses original current .65 bus instead of legacy .6')
 Levels.Set('sfx',.1);V.assert(math.abs(slot.source.gain-base*.1)<1e-6,'active original SFX immediately follows slider')
 intro:Voice('test');Levels.Set('voice',.3);V.assert(math.abs(intro.voice.gain-.45)<1e-6,'active voice immediately follows original relative gain')
 intro:Music('test',{vol=.5,fade=0});local music=intro.music[intro.musicIndex]
 Levels.Set('music',.25);local ratio=.5*.9*Levels.MusicGain(.25)/Levels.MusicGain(.75)
 V.assert(math.abs(music.source.gain-ratio*.55)<1e-6,'voice duck begins at original unducked music level')
 V.assert(math.abs(intro:DuckLevel(intro.time+.075)-(.55+.24)/2)<1e-8,'source voice duck reaches midpoint at .075 seconds')
 V.assert(math.abs(intro:DuckLevel(intro.time+.15)-.24)<1e-8,'source voice duck reaches .24 after .15 seconds')
 intro:StopVoice();intro:Duck(true);intro:Update(.15,true)
 V.assert(math.abs(music.source.gain-ratio*.24)<1e-6,'active intro music applies original .15 second voice duck')
 intro:StopVoice();intro:Update(.3,true)
 V.assert(math.abs(music.source.gain-ratio*(.24+.55)/2)<1e-6,'source music recovery reaches midpoint after .3 seconds')
 intro:Update(.3,true)
 V.assert(math.abs(music.source.gain-ratio*.55)<1e-6,'source music recovery returns to .55 after .6 seconds')
 Levels.Set('music',0);V.assert(music.source.gain==0,'zero music slider instantly silences original intro music')
 local source=intro.voice;intro:Dispose();Levels.Set('voice',.4);V.assert(#intro.unwatch==0,'intro disposal releases all audio level subscriptions')
 local owner={};Levels.SetSpeaking(owner,true);V.assert(Levels.Speaking(),'story voice owns music duck');Levels.SetSpeaking(owner,false);V.assert(not Levels.Speaking(),'finished voice releases music duck')
 local Player=require 'audio.MusicPlayer';local player=Player.New(nil);player:Update(0,'hangar',false)
 Levels.Set('music',.2);V.assert(player.volume==.2,'shared music player instantly follows global source control')
 player:SetVolume(.4);V.assert(Levels.Get('music')==.4,'music box slider writes same source global level')
 player:SetEnabled(false);V.assert(Levels.Get('musicEnabled')==false and not player:CanPlay(),'shared scene music enabled setting controls retained player')
 player:SetEnabled(true);player.unlocked=false;Levels.SetSpeaking(owner,true);player:Update(.12,'hangar',false)
 V.assert(math.abs(player.duckLevel-(.5+.5/math.exp(1)))<1e-8,'source .12 second voice duck response')
 Levels.SetSpeaking(owner,false);local previous=player.duckLevel;player:Update(1.2,'hangar',false)
 V.assert(math.abs(player.duckLevel-(1+(previous-1)/math.exp(1)))<1e-8,'source 1.2 second music release response')
 player:Dispose();Levels.Set('music',.3);V.assert(#player.unwatch==0,'retired music player releases source settings subscriptions')
 audio:SetMasterGain('VoxAudioHeadroomProbe',1.5)
 print('[AudioLevels] masterGainRequested=1.5 masterGainActual='..audio:GetMasterGain('VoxAudioHeadroomProbe'))
 local node=Scene();local source=node:CreateChild('GainProbe'):CreateComponent('SoundSource');source.gain=1.5
 print('[AudioLevels] sourceGainRequested=1.5 sourceGainActual='..source.gain)
 Levels.Init(nil);source.soundType='VoxMatchVoice';Levels.Play(source,sound,0,.7)
 V.assert(math.abs(source.gain-.7)<1e-6,'source voice wrapper retains calibrated default gain')
 Levels.Set('voice',1);V.assert(math.abs(source.gain-.7/.6)<1e-6,'voice level above source default actually increases native gain beyond one')
 Levels.SetGain(source,.35);V.assert(math.abs(source.gain-.35/.6)<1e-6,'voice fade recomputes from raw authored gain without compounding')
 Levels.Set('voice',.6);V.assert(math.abs(source.gain-.35)<1e-6 and Levels.RawGain(source)==.35,'return to source default exactly restores raw authored gain')
 Levels.Set('voice',0);V.assert(source.gain==0,'global voice mute instantly silences an already playing source')
 source:StopImmediate();source.soundType='VoxWeapons';Levels.Play(source,sound,0,.5)
 Levels.Set('sfx',1);V.assert(math.abs(source.gain-.5/.65)<1e-6,'global SFX slider affects already playing shared weapon source')
 Levels.Set('voice',.2);V.assert(math.abs(source.gain-.5/.65)<1e-6,'voice slider cannot alter independent SFX bus')
 node:Dispose();Levels.Set('sfx',.3);V.assert(true,'disposed tracked sources do not break later audio setting changes')
 Levels.Init(nil);V.finish()
end)
